SELECT post.id, post.org_id, post.post_code, post.post_name



        AND post.id IN
        #{postId}

    AND 1 = 0

AND post.org_id = #{orgId}
ORDER BY post.id

SELECT post.id, post.org_id, post.post_code, post.post_name

AND post.org_id = #{orgId}

    AND (post.post_code LIKE CONCAT('%', #{keyword}, '%') OR post.post_name LIKE CONCAT('%', #{keyword}, '%'))

AND post.id > #{afterPostId}
ORDER BY post.id
LIMIT #{limit}

SELECT post.id, post.org_id, post.post_code, post.post_name

AND post.org_id IS NULL

    AND (post.post_code LIKE CONCAT('%', #{keyword}, '%') OR post.post_name LIKE CONCAT('%', #{keyword}, '%'))

AND post.id > #{afterPostId}
ORDER BY post.id
LIMIT #{limit}
